  "8": [
    {
      "id": 801,
      "lesson_id": 8,
      "title": "奈良はどんな所ですか — Nara là nơi thế nào?",
      "content": [
        {
          "text": "奈良は古い町です。",
          "furigana": "ならはふるいまちです",
          "meaning": "Nara là một thành phố cổ.",
          "note": "Tính từ い đứng trực tiếp trước danh từ."
        },
        {
          "text": "静かな所です。",
          "furigana": "しずかなところです",
          "meaning": "Đó là một nơi yên tĩnh.",
          "note": "Tính từ な thêm な khi đứng trước danh từ."
        },
        {
          "text": "きれいなお寺がたくさんあります。",
          "furigana": "きれいなおてらがたくさんあります",
          "meaning": "Có nhiều ngôi chùa đẹp.",
          "note": "きれい là tính từ な dù kết thúc bằng い."
        },
        {
          "text": "奈良の食べ物はおいしいです。",
          "furigana": "ならのたべものはおいしいです",
          "meaning": "Đồ ăn ở Nara ngon.",
          "note": "おいしい là tính từ い."
        },
        {
          "text": "町はあまりにぎやかじゃありません。",
          "furigana": "まちはあまりにぎやかじゃありません",
          "meaning": "Thành phố không nhộn nhịp lắm.",
          "note": "あまり đi với dạng phủ định: không... lắm."
        },
        {
          "text": "でも、とてもきれいです。",
          "furigana": "でも、とてもきれいです",
          "meaning": "Nhưng nơi đó rất đẹp.",
          "note": "とても nhấn mạnh mức độ: rất."
        },
        {
          "text": "奈良の旅行は楽しいです。",
          "furigana": "ならのりょこうはたのしいです",
          "meaning": "Chuyến du lịch Nara rất vui.",
          "note": "楽しい mô tả sự vui vẻ, thú vị."
        }
      ]
    }
  ],
